"""Pure Python SX1302 HAL — direct spidev implementation.

Replaces ctypes bindings to libloragw.so.  Talks to the SX1302 LoRa
concentrator and SX1250 RF frontends directly via Linux spidev.

Supported hardware:
    SX1302 / SX1303 concentrator with SX1250 radios (WM1302 module).

Usage:
    from sx1302_meshcore_kiss.sx1302 import hal
    hal.lgw_board_setconf(board_cfg)
    hal.lgw_rxrf_setconf(0, rf_cfg_a)
    hal.lgw_rxrf_setconf(1, rf_cfg_b)
    hal.lgw_rxif_setconf(0, if_cfg)
    hal.lgw_start()
    pkts = hal.lgw_receive(10)
    hal.lgw_send(pkt)
    hal.lgw_stop()

Note:
    SX1302 normally exposes 125 / 250 / 500 kHz bandwidth. Higher-level
    wrappers may allow 62.5 kHz as an experimental trick mode and encode it
    through the 125 kHz HAL bandwidth path until that trick is modeled here.
    Requires Linux spidev (CONFIG_SPI_SPIDEV) and appropriate permissions.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass, field, is_dataclass
import logging
import math
import struct
import time
from typing import Any, Dict, List, Optional, Tuple

try:
    import spidev  # type: ignore
    _SPIDEV_AVAILABLE = True
except ImportError:  # not on host — allow import for testing
    spidev = None  # type: ignore
    _SPIDEV_AVAILABLE = False

log = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Public constants
# ---------------------------------------------------------------------------

LGW_HAL_SUCCESS = 0
LGW_HAL_ERROR = -1
LGW_LBT_NOT_ALLOWED = 1

# Modulation identifiers
MOD_UNDEFINED = 0
MOD_LORA = 0x10
MOD_FSK = 0x20
MOD_CW = 0x30

# Bandwidth codes
BW_UNDEFINED = 0
BW_125KHZ = 0x01
BW_250KHZ = 0x02
BW_500KHZ = 0x03

# LoRa spreading factor codes
DR_UNDEFINED = 0
DR_LORA_SF5 = 5
DR_LORA_SF6 = 6
DR_LORA_SF7 = 7
DR_LORA_SF8 = 8
DR_LORA_SF9 = 9
DR_LORA_SF10 = 10
DR_LORA_SF11 = 11
DR_LORA_SF12 = 12
DR_LORA_MULTI = 0x7F

# LoRa coding rate codes
CR_UNDEFINED = 0
CR_LORA_4_5 = 0x01
CR_LORA_4_6 = 0x02
CR_LORA_4_7 = 0x03
CR_LORA_4_8 = 0x04

# Radio type
RADIO_TYPE_NONE = 0
RADIO_TYPE_SX1255 = 1
RADIO_TYPE_SX1257 = 2
RADIO_TYPE_SX1250 = 3

# TX trigger modes
TX_IMMEDIATE = 0
TX_TIMESTAMPED = 1

# Values accepted by lgw_status(select)
TX_STATUS = 1
RX_STATUS = 2

# TX status codes
TX_STATUS_UNKNOWN = 0
TX_OFF = 1
TX_FREE = 2
TX_SCHEDULED = 3
TX_EMITTING = 4

# RX status codes
RX_STATUS_UNKNOWN = 0
RX_OFF = 1
RX_ON = 2
RX_SUSPENDED = 3

# Concentrator capacity constants
LGW_RF_CHAIN_NB = 2
LGW_IF_CHAIN_NB = 10
LGW_LBT_CHANNEL_NB_MAX = 16
LGW_SPECTRAL_SCAN_RESULT_SIZE = 33


@dataclass(frozen=True)
class SX1302Capabilities:
    """Feature flags for the pure-Python SX1302 HAL.

    These flags intentionally describe what this Python implementation exposes
    today, not every feature present in Semtech's C HAL. Advanced features
    should only be flipped to True after a tested implementation exists.
    """

    sx1302: bool = True
    sx1250: bool = True
    sx1261_companion: bool = True
    hardware_lbt: bool = False
    software_lbt: bool = True
    spectral_scan: bool = False
    fine_timestamp: bool = False
    timestamped_tx: bool = False
    gps_tx: bool = False
    fsk: bool = False
    cw: bool = False
    usb: bool = False


def get_capabilities() -> SX1302Capabilities:
    """Return supported SX1302 HAL capabilities for this implementation."""
    return SX1302Capabilities()


@dataclass(frozen=True)
class BoardConfig:
    """Gateway board configuration accepted by :func:`lgw_board_setconf`."""

    spi_path: str = "/dev/spidev0.0"
    lorawan_public: bool = True
    clock_source: int = 0
    full_duplex: bool = False


@dataclass(frozen=True)
class RxRfConfig:
    """SX125x RF-chain configuration accepted by :func:`lgw_rxrf_setconf`."""

    enable: bool
    freq_hz: int
    rssi_offset: float = 0.0
    type: int = RADIO_TYPE_SX1250
    tx_enable: bool = False
    single_input_mode: bool = False


@dataclass(frozen=True)
class RxIfConfig:
    """SX1302 IF-chain configuration accepted by :func:`lgw_rxif_setconf`."""

    enable: bool
    rf_chain: int
    freq_hz: int
    bandwidth: int = BW_125KHZ
    datarate: int = DR_LORA_MULTI
    sync_word: int = 0


@dataclass(frozen=True)
class TxGainLutEntry:
    """One TX gain LUT entry for :class:`TxGainLutConfig`."""

    rf_power: int
    pa_gain: int = 0
    dig_gain: int = 0
    dac_gain: int = 0
    mix_gain: int = 0


@dataclass(frozen=True)
class TxGainLutConfig:
    """TX gain lookup table accepted by :func:`lgw_txgain_setconf`."""

    lut: List[Any] = field(default_factory=list)


@dataclass(frozen=True)
class Sx1261LbtChannelConfig:
    """One SX1261 LBT scan channel.

    This mirrors the shape of Semtech's LBT channel configuration enough for
    higher layers to build CAD/LBT policies without committing to the final
    register-level implementation yet.
    """

    freq_hz: int
    bandwidth_hz: int = 125_000
    scan_time_us: int = 128
    transmit_time_ms: int = 4000


@dataclass(frozen=True)
class Sx1261LbtConfig:
    """SX1261 listen-before-talk configuration scaffold."""

    enable: bool = False
    rssi_target: int = -80
    channels: List[Any] = field(default_factory=list)


@dataclass(frozen=True)
class Sx1261Config:
    """SX1261 companion-chip configuration accepted by :func:`lgw_sx1261_setconf`."""

    enable: bool = False
    spi_path: Optional[str] = None
    rssi_offset: float = 0.0
    spectral_scan_enable: bool = False
    lbt: Any = field(default_factory=Sx1261LbtConfig)


def _normalize_config(conf: Any) -> Dict[str, Any]:
    """Return a plain mutable dict for legacy dict or typed dataclass configs."""
    if is_dataclass(conf):
        data = asdict(conf)
    else:
        data = dict(conf)

    # Preserve Semtech C HAL naming internally while exposing clearer Python
    # field names to callers.
    if "clock_source" in data:
        data["clksrc"] = data.pop("clock_source")
    return data


# Firmware version expected by this HAL
_FW_VERSION_AGC_SX1250 = 10
_FW_VERSION_ARB = 2

# MCU memory layout (paged EXT_MEM at page 0)
_AGC_MEM_ADDR = 0x0000
_ARB_MEM_ADDR = 0x2000
_MCU_FW_SIZE = 8192

# RX FIFO base address (not paged)
_RX_BUFFER_BASE_ADDR = 0x4000

# SX1302 SPI MUX target byte (prefixed to every 16-bit register address)
_SPI_MUX_TARGET_SX1302 = 0x00
_SPI_MUX_TARGET_RADIOA = 0x01
_SPI_MUX_TARGET_RADIOB = 0x02

# RX packet buffer syncword
_PKT_SYNCWORD_H = 0xA5
_PKT_SYNCWORD_L = 0xC0
_PKT_HEAD_METADATA = 9
_PKT_TAIL_METADATA = 14

