# ---------------------------------------------------------------------------
# Low-level SPI helpers
# ---------------------------------------------------------------------------


def _spi_open(spi_path: str) -> None:
    """Open the SX1302 spidev device.

    Args:
        spi_path: Linux spidev path, e.g. ``/dev/spidev0.0``.

    Raises:
        RuntimeError: If spidev is not available or device cannot be opened.
    """
    global _spi
    if not _SPIDEV_AVAILABLE:
        raise RuntimeError(
            "spidev module not available; install the hardware extra with "
            "install the daemon hardware dependencies and verify the Linux SPI device "
            f"exists and is accessible at {spi_path}"
        )
    parts = spi_path.replace("/dev/spidev", "").split(".")
    bus, dev = int(parts[0]), int(parts[1])
    _spi = spidev.SpiDev()
    _spi.open(bus, dev)
    _spi.max_speed_hz = 2_000_000  # match C SPI_SPEED from loragw_spi.h
    _spi.mode = 0
    log.debug("SPI opened: %s (bus=%d dev=%d)", spi_path, bus, dev)


def _spi_close() -> None:
    """Close the SX1302 spidev device."""
    global _spi
    if _spi is not None:
        _spi.close()
        _spi = None


def _spi_write(target: int, addr: int, data: bytes) -> None:
    """Write bytes to an SX1302 register address.

    Args:
        target: SPI MUX target byte (0x00 for SX1302).
        addr: 16-bit register address.
        data: Bytes to write.
    """
    if _spi is None:
        raise RuntimeError("SPI not open")
    # Frame: [mux_target, 0x80|addr_msb, addr_lsb, data...]  (C: lgw_spi_wb)
    frame = [target, 0x80 | ((addr >> 8) & 0x7F), addr & 0xFF] + list(data)
    _spi.xfer2(frame)


def _spi_read(target: int, addr: int, length: int) -> bytes:
    """Read bytes from an SX1302 register address.

    Args:
        target: SPI MUX target byte (0x00 for SX1302).
        addr: 16-bit register address.
        length: Number of bytes to read.

    Returns:
        Raw bytes read from the device.
    """
    if _spi is None:
        raise RuntimeError("SPI not open")
    # Frame: [mux_target, addr_msb, addr_lsb, dummy, data x length]  (C: lgw_spi_rb)
    # READ_ACCESS = 0x00, so addr_msb has no write bit set
    frame = [target, (addr >> 8) & 0x7F, addr & 0xFF, 0x00] + [0x00] * length
    resp = _spi.xfer2(frame)
    return bytes(resp[4:])  # first 4 bytes are header echo


def _mem_write(base_addr: int, data: bytes) -> None:
    """Bulk-write to paged EXT_MEM in chunks.

    Args:
        base_addr: Starting address within EXT_MEM (e.g. 0x0000 or 0x2000).
        data: Raw bytes to write.
    """
    chunk = 64
    offset = 0
    while offset < len(data):
        block = data[offset: offset + chunk]
        _spi_write(_SPI_MUX_TARGET_SX1302, base_addr + offset, block)
        offset += len(block)


def _mem_read(base_addr: int, length: int) -> bytes:
    """Bulk-read from paged EXT_MEM.

    Args:
        base_addr: Starting address within EXT_MEM.
        length: Number of bytes to read.

    Returns:
        Raw bytes read.
    """
    chunk = 64
    result = b""
    offset = 0
    while offset < length:
        n = min(chunk, length - offset)
        result += _spi_read(_SPI_MUX_TARGET_SX1302, base_addr + offset, n)
        offset += n
    return result


# ---------------------------------------------------------------------------
# Register access
# ---------------------------------------------------------------------------


def _reg_entry(name: str) -> Tuple[int, int, int, int, int, int, int, int]:
    """Return register tuple for the given name."""
    entry = _REG.get(name)
    if entry is None:
        raise KeyError(f"Unknown register: {name}")
    return entry


def _reg_w(name: str, value: int) -> None:
    """Write a bitfield register by name.

    Performs read-modify-write when the field does not occupy the full byte.

    Args:
        name: Register name from _REG.
        value: Integer value to write (masked to field width).

    Raises:
        KeyError: If register name is unknown.
        ValueError: If register is read-only.
    """
    _page, addr, offs, _sign, leng, rdon, _chck, _dflt = _reg_entry(name)
    if rdon:
        raise ValueError(f"Register {name!r} is read-only")
    mask = ((1 << leng) - 1) << offs
    value_shifted = (int(value) & ((1 << leng) - 1)) << offs
    if leng == 8 and offs == 0:
        # Full byte — no read needed
        _spi_write(_SPI_MUX_TARGET_SX1302, addr, bytes([value_shifted & 0xFF]))
    else:
        current = _spi_read(_SPI_MUX_TARGET_SX1302, addr, 1)[0]
        new_val = (current & ~mask) | value_shifted
        _spi_write(_SPI_MUX_TARGET_SX1302, addr, bytes([new_val & 0xFF]))


def _reg_r(name: str) -> int:
    """Read a bitfield register by name.

    Applies sign extension for signed fields.

    Args:
        name: Register name from _REG.

    Returns:
        Integer value of the field (sign-extended if field is signed).

    Raises:
        KeyError: If register name is unknown.
    """
    _page, addr, offs, sign, leng, _rdon, _chck, _dflt = _reg_entry(name)
    raw = _spi_read(_SPI_MUX_TARGET_SX1302, addr, 1)[0]
    value = (raw >> offs) & ((1 << leng) - 1)
    if sign and value >= (1 << (leng - 1)):
        value -= (1 << leng)
    return value


def _reg_wb(name: str, data: bytes) -> None:
    """Bulk-write raw bytes to the address of a register (no bit masking).

    Args:
        name: Register name whose address is the write target.
        data: Raw bytes to write.
    """
    _page, addr, _offs, _sign, _leng, _rdon, _chck, _dflt = _reg_entry(name)
    _spi_write(_SPI_MUX_TARGET_SX1302, addr, data)


def _reg_rb(name: str, length: int) -> bytes:
    """Bulk-read raw bytes from the address of a register.

    Args:
        name: Register name whose address is the read target.
        length: Number of bytes to read.

    Returns:
        Raw bytes.
    """
    _page, addr, _offs, _sign, _leng, _rdon, _chck, _dflt = _reg_entry(name)
    return _spi_read(_SPI_MUX_TARGET_SX1302, addr, length)


def _select_page(page: int) -> None:
    """Select the SPI register page via COMMON_PAGE_PAGE.

    Args:
        page: Page number (0-3).
    """
    _reg_w("COMMON_PAGE_PAGE", page)


# ---------------------------------------------------------------------------
# SX1250 radio driver (SPI via dedicated radio SPI mux channels)
# ---------------------------------------------------------------------------

# SX1250 OpCode commands (from sx1250_defs.h)
_SX1250_SET_STANDBY = 0x80
_SX1250_CALIBRATE = 0x89          # calibrate all blocks (0x7F)
_SX1250_CALIBRATE_IMAGE = 0x98   # image calibration with band-specific bytes
_SX1250_GET_DEVICE_ERRORS = 0x17
_SX1250_SET_RF_FREQUENCY = 0x86
_SX1250_GET_STATUS = 0xC0
_SX1250_SET_RX = 0x82
_SX1250_WRITE_REGISTER = 0x0D
_SX1250_STANDBY_RC = 0x00
_SX1250_STANDBY_XOSC = 0x01
_SX1250_STATUS_STANDBY_RC = 0x02
_SX1250_STATUS_STANDBY_XOSC = 0x03

# Radio SPI MUX targets
_RADIO_TARGET = [_SPI_MUX_TARGET_RADIOA, _SPI_MUX_TARGET_RADIOB]


def _sx1250_cmd_w(rf_chain: int, opcode: int, data: bytes) -> None:
    """Send an SX1250 OpCode command via the SX1302 SPI mux.

    SX1250 SPI frame: [mux_target, op_code, data...] — NOT the SX1302 register format.
    Matches C sx1250_spi_w(): out_buf[0]=spi_mux_target, out_buf[1]=op_code, out_buf[2+]=data
    """
    if _spi is None:
        raise RuntimeError("SPI not open")
    time.sleep(0.001)  # WAIT_BUSY_SX1250_MS
    frame = [_RADIO_TARGET[rf_chain], opcode] + list(data)
    _spi.xfer2(frame)


def _sx1250_cmd_r(rf_chain: int, opcode: int, length: int) -> bytes:
    """Read from SX1250 via OpCode command.

    Matches C sx1250_spi_r(): send [target, op_code, nop*length], response at in_buf[2:].
    """
    if _spi is None:
        raise RuntimeError("SPI not open")
    time.sleep(0.001)  # WAIT_BUSY_SX1250_MS
    frame = [_RADIO_TARGET[rf_chain], opcode] + [0x00] * length
    resp = _spi.xfer2(frame)
    return bytes(resp[2:])


def _sx1250_calibrate(rf_chain: int, freq_hz: int) -> None:
    """Run SX1250 image calibration (called during sx1302_radio_calibrate phase).

    Uses CALIBRATE_IMAGE with band-specific bytes, matches C sx1250_calibrate().
    """
    status = _sx1250_cmd_r(rf_chain, _SX1250_GET_STATUS, 1)[0]
    log.debug("sx1250_calibrate chain=%d pre-cal status=0x%02x", rf_chain, status)

    # Band-specific image calibration bytes (from C sx1250_calibrate)
    if 430e6 < freq_hz < 440e6:
        cal = bytes([0x6B, 0x6F])
    elif 470e6 < freq_hz < 510e6:
        cal = bytes([0x75, 0x81])
    elif 779e6 < freq_hz < 787e6:
        cal = bytes([0xC1, 0xC5])
    elif 863e6 < freq_hz < 870e6:
        cal = bytes([0xD7, 0xDB])
    elif 902e6 < freq_hz < 928e6:
        cal = bytes([0xE1, 0xE9])
    else:
        raise ValueError(f"Frequency {freq_hz} Hz not in a supported calibration band")

    _sx1250_cmd_w(rf_chain, _SX1250_CALIBRATE_IMAGE, cal)
    time.sleep(0.01)

    errors = _sx1250_cmd_r(rf_chain, _SX1250_GET_DEVICE_ERRORS, 3)
    if errors[2] & (1 << 4):
        log.error("SX1250 chain %d image calibration error (errors=0x%02x%02x%02x)",
                  rf_chain, errors[0], errors[1], errors[2])


def _sx1250_setup(rf_chain: int, freq_hz: int, single_input_mode: bool) -> None:
    """Configure an SX1250 radio for continuous receive.

    Matches C sx1250_setup() exactly. All SX1250 internal register writes use the
    WRITE_REGISTER (0x0D) opcode, NOT the SX1302 register SPI format.
    """
    # Set Standby RC
    _sx1250_cmd_w(rf_chain, _SX1250_SET_STANDBY, bytes([_SX1250_STANDBY_RC]))
    time.sleep(0.01)

    # Verify STANDBY_RC
    status = _sx1250_cmd_r(rf_chain, _SX1250_GET_STATUS, 1)[0]
    mode = (status >> 4) & 0x07
    if mode != _SX1250_STATUS_STANDBY_RC:
        log.warning("sx1250_setup chain=%d: expected STANDBY_RC (0x02) got 0x%02x", rf_chain, mode)

    # Calibrate all blocks
    _sx1250_cmd_w(rf_chain, _SX1250_CALIBRATE, bytes([0x7F]))
    time.sleep(0.01)

    # Set Standby XOSC
    _sx1250_cmd_w(rf_chain, _SX1250_SET_STANDBY, bytes([_SX1250_STANDBY_XOSC]))
    time.sleep(0.01)

    # Verify STANDBY_XOSC
    status = _sx1250_cmd_r(rf_chain, _SX1250_GET_STATUS, 1)[0]
    mode = (status >> 4) & 0x07
    if mode != _SX1250_STATUS_STANDBY_XOSC:
        log.warning("sx1250_setup chain=%d: expected STANDBY_XOSC (0x03) got 0x%02x", rf_chain, mode)

    # Set maximum bitrate (lowers TX→FS switch time): registers 0x06A1-0x06A3
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x06, 0xA1, 0x01]))
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x06, 0xA2, 0x00]))
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x06, 0xA3, 0x00]))

    # Configure DIO for Rx (drive strength, input/pull config, output enable)
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x05, 0x82, 0x00]))  # drive strength min
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x05, 0x83, 0x00]))  # input disabled
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x05, 0x84, 0x00]))  # no pull-up
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x05, 0x85, 0x00]))  # no pull-down
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x05, 0x80, 0x00]))  # output enable all

    # Set fix gain
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x08, 0xB6, 0x2A]))

    # Set RF frequency (4 bytes, big-endian): SX1250_FREQ_TO_REG = freq * 2^25 / 32MHz
    freq_word = (freq_hz * (1 << 25)) // 32_000_000
    _sx1250_cmd_w(rf_chain, _SX1250_SET_RF_FREQUENCY, struct.pack(">I", freq_word))

    # Zero frequency offset (register 0x088F, 5 bytes)
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x08, 0x8F, 0x00, 0x00, 0x00]))

    # Set continuous RX (0xFFFFFF timeout = continuous)
    _sx1250_cmd_w(rf_chain, _SX1250_SET_RX, bytes([0xFF, 0xFF, 0xFF]))

    # Optional single-input mode
    if single_input_mode:
        _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x08, 0xE2, 0x0D]))

    # FPGA RX mode
    _sx1250_cmd_w(rf_chain, _SX1250_WRITE_REGISTER, bytes([0x05, 0x87, 0x0B]))
    log.debug("sx1250_setup chain=%d freq=%d Hz done", rf_chain, freq_hz)


# ---------------------------------------------------------------------------
# AGC / ARB firmware load and start
# ---------------------------------------------------------------------------


def _agc_load_firmware(firmware: bytes) -> int:
    """Load AGC MCU firmware into SX1302 and verify.

    Args:
        firmware: Exactly 8192 bytes of MCU firmware.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.
    """
    _reg_w("AGC_MCU_CTRL_MCU_CLEAR", 1)
    _reg_w("AGC_MCU_CTRL_HOST_PROG", 1)
    _select_page(0)
    _mem_write(_AGC_MEM_ADDR, firmware)
    readback = _mem_read(_AGC_MEM_ADDR, _MCU_FW_SIZE)
    if readback != firmware:
        log.error("AGC firmware verification failed")
        return LGW_HAL_ERROR
    _reg_w("AGC_MCU_CTRL_HOST_PROG", 0)
    # Clear WR mailbox — previous-run trigger bytes (e.g. 0x80 in BYTE3) would
    # fire immediately when the MCU starts, skipping the 0x01 wait.
    _reg_w("AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE3_MCU_MAIL_BOX_WR_DATA", 0)
    _reg_w("AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE2_MCU_MAIL_BOX_WR_DATA", 0)
    _reg_w("AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE1_MCU_MAIL_BOX_WR_DATA", 0)
    _reg_w("AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE0_MCU_MAIL_BOX_WR_DATA", 0)
    # CLK_EN must be 1 before releasing MCU_CLEAR. The MCU clears its own
    # CLK_EN bit after starting; without a hardware reset we must restore it.
    _reg_w("AGC_MCU_CTRL_CLK_EN", 1)
    _reg_w("AGC_MCU_CTRL_MCU_CLEAR", 0)
    if _reg_r("AGC_MCU_CTRL_PARITY_ERROR") != 0:
        log.error("AGC MCU parity error after load")
        return LGW_HAL_ERROR
    log.debug("AGC firmware loaded OK (%d bytes)", len(firmware))
    return LGW_HAL_SUCCESS


def _arb_load_firmware(firmware: bytes) -> int:
    """Load ARB MCU firmware into SX1302 and verify.

    Args:
        firmware: Exactly 8192 bytes of MCU firmware.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.
    """
    _reg_w("ARB_MCU_CTRL_MCU_CLEAR", 1)
    _reg_w("ARB_MCU_CTRL_HOST_PROG", 1)
    _select_page(0)
    _mem_write(_ARB_MEM_ADDR, firmware)
    readback = _mem_read(_ARB_MEM_ADDR, _MCU_FW_SIZE)
    if readback != firmware:
        log.error("ARB firmware verification failed")
        return LGW_HAL_ERROR
    _reg_w("ARB_MCU_CTRL_HOST_PROG", 0)
    # Clear DEBUG_CFG_1 (resume signal). If left at 1 from a previous run, the
    # ARB skips STATUS=0x01 instantly and we never catch it.
    _reg_w("ARB_MCU_ARB_DEBUG_CFG_1_ARB_DEBUG_CFG_1", 0)
    _reg_w("ARB_MCU_CTRL_CLK_EN", 1)
    _reg_w("ARB_MCU_CTRL_MCU_CLEAR", 0)
    if _reg_r("ARB_MCU_CTRL_PARITY_ERROR") != 0:
        log.error("ARB MCU parity error after load")
        return LGW_HAL_ERROR
    log.debug("ARB firmware loaded OK (%d bytes)", len(firmware))
    return LGW_HAL_SUCCESS


def _agc_mailbox_wait(status_val: int, timeout: float = 3.0) -> bool:
    """Wait for AGC MCU mailbox status to reach the given value.

    Args:
        status_val: Expected status byte.
        timeout: Maximum wait time in seconds.

    Returns:
        True if status reached within timeout, False otherwise.
    """
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        if _reg_r("AGC_MCU_MCU_AGC_STATUS_MCU_AGC_STATUS") == status_val:
            return True
        time.sleep(0.001)
    actual = _reg_r("AGC_MCU_MCU_AGC_STATUS_MCU_AGC_STATUS")
    log.error("AGC mailbox timeout waiting for 0x%02X, actual=0x%02X", status_val, actual)
    return False


def _agc_mb_w(byte_idx: int, val: int) -> None:
    """Write one byte to AGC mailbox."""
    names = [
        "AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE0_MCU_MAIL_BOX_WR_DATA",
        "AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE1_MCU_MAIL_BOX_WR_DATA",
        "AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE2_MCU_MAIL_BOX_WR_DATA",
        "AGC_MCU_MCU_MAIL_BOX_WR_DATA_BYTE3_MCU_MAIL_BOX_WR_DATA",
    ]
    _reg_w(names[byte_idx], val)


def _agc_mb_r(byte_idx: int) -> int:
    """Read one byte from AGC mailbox."""
    names = [
        "AGC_MCU_MCU_MAIL_BOX_RD_DATA_BYTE0_MCU_MAIL_BOX_RD_DATA",
        "AGC_MCU_MCU_MAIL_BOX_RD_DATA_BYTE1_MCU_MAIL_BOX_RD_DATA",
        "AGC_MCU_MCU_MAIL_BOX_RD_DATA_BYTE2_MCU_MAIL_BOX_RD_DATA",
        "AGC_MCU_MCU_MAIL_BOX_RD_DATA_BYTE3_MCU_MAIL_BOX_RD_DATA",
    ]
    return _reg_r(names[byte_idx])


def _agc_start(ana_gain: int = 0xFF, dec_gain: int = 0xFF) -> int:
    """Execute the AGC MCU startup handshake sequence.

    Matches C sx1302_agc_start() exactly. All trigger values and gain table
    parameters are from loragw_agc_params.h / loragw_sx1302.c.

    Args:
        ana_gain: Analogue gain (0xFF = SX1302_AGC_RADIO_GAIN_AUTO).
        dec_gain: Decimation gain (0xFF = SX1302_AGC_RADIO_GAIN_AUTO).

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.
    """
    # AGC param table for SX1250 (from loragw_agc_params.h agc_params_sx1250)
    ANA_MIN, ANA_MAX = 1, 13
    ANA_THRESH_L, ANA_THRESH_H = 3, 12
    DEC_ATTN_MIN, DEC_ATTN_MAX = 4, 15
    DEC_THRESH_L, DEC_THRESH_H1, DEC_THRESH_H2 = 40, 80, 90
    CHAN_ATTN_MIN, CHAN_ATTN_MAX = 4, 14
    CHAN_THRESH_L, CHAN_THRESH_H = 52, 132
    DEVICE_SEL, HP_MAX, PA_DUTY_CYCLE = 0, 7, 4
    PA_START_DELAY = 8  # 100 µs per LSB

    # AGC init triggers (from loragw_sx1302.c)
    AGC_RADIO_A_INIT_DONE = 0x80
    AGC_RADIO_B_INIT_DONE = 0x20

    # Wait for AGC MCU to start and post version in mailbox[0]
    if not _agc_mailbox_wait(0x01):
        return LGW_HAL_ERROR
    version = _agc_mb_r(0)
    if version != _FW_VERSION_AGC_SX1250:
        log.error("AGC FW version mismatch: got %d expected %d", version, _FW_VERSION_AGC_SX1250)
        return LGW_HAL_ERROR
    log.debug("AGC FW version: %d", version)

    # Radio A: write gain settings, trigger with 0x80, wait for 0x02
    _agc_mb_w(0, ana_gain)
    _agc_mb_w(1, dec_gain)
    # Note: fdd_mode (byte2) NOT written for SX1250 (C code skips it)
    _agc_mb_w(3, AGC_RADIO_A_INIT_DONE)
    if not _agc_mailbox_wait(0x02):
        return LGW_HAL_ERROR

    # Radio B: same gains, trigger with 0x20, wait for 0x03
    _agc_mb_w(0, ana_gain)
    _agc_mb_w(1, dec_gain)
    _agc_mb_w(3, AGC_RADIO_B_INIT_DONE)
    if not _agc_mailbox_wait(0x03):
        return LGW_HAL_ERROR

    # Ana gain min/max → 0x04
    _agc_mb_w(0, ANA_MIN)
    _agc_mb_w(1, ANA_MAX)
    _agc_mb_w(3, 0x03)
    if not _agc_mailbox_wait(0x04):
        return LGW_HAL_ERROR

    # Ana thresholds → 0x05
    _agc_mb_w(0, ANA_THRESH_L)
    _agc_mb_w(1, ANA_THRESH_H)
    _agc_mb_w(3, 0x04)
    if not _agc_mailbox_wait(0x05):
        return LGW_HAL_ERROR

    # Dec attenuation min/max → 0x06
    _agc_mb_w(0, DEC_ATTN_MIN)
    _agc_mb_w(1, DEC_ATTN_MAX)
    _agc_mb_w(3, 0x05)
    if not _agc_mailbox_wait(0x06):
        return LGW_HAL_ERROR

    # Dec thresholds → 0x07
    _agc_mb_w(0, DEC_THRESH_L)
    _agc_mb_w(1, DEC_THRESH_H1)
    _agc_mb_w(2, DEC_THRESH_H2)
    _agc_mb_w(3, 0x06)
    if not _agc_mailbox_wait(0x07):
        return LGW_HAL_ERROR

    # Chan attenuation min/max → 0x08
    _agc_mb_w(0, CHAN_ATTN_MIN)
    _agc_mb_w(1, CHAN_ATTN_MAX)
    _agc_mb_w(3, 0x07)
    if not _agc_mailbox_wait(0x08):
        return LGW_HAL_ERROR

    # Chan thresholds → 0x09
    _agc_mb_w(0, CHAN_THRESH_L)
    _agc_mb_w(1, CHAN_THRESH_H)
    _agc_mb_w(3, 0x08)
    if not _agc_mailbox_wait(0x09):
        return LGW_HAL_ERROR

    # SX1250-specific: PA config (deviceSel, hpMax, paDutyCycle) → 0x0A
    _agc_mb_w(0, DEVICE_SEL)
    _agc_mb_w(1, HP_MAX)
    _agc_mb_w(2, PA_DUTY_CYCLE)
    _agc_mb_w(3, 0x09)
    if not _agc_mailbox_wait(0x0A):
        return LGW_HAL_ERROR

    # PA start delay → 0x0B
    _agc_mb_w(0, PA_START_DELAY)
    _agc_mb_w(3, 0x0A)
    if not _agc_mailbox_wait(0x0B):
        return LGW_HAL_ERROR

    # LBT enable (disabled) → 0x0F
    _agc_mb_w(0, 0)   # lbt_enable = false
    _agc_mb_w(3, 0x0B)
    if not _agc_mailbox_wait(0x0F):
        return LGW_HAL_ERROR

    # Signal configuration complete
    _agc_mb_w(3, 0x0F)

    log.debug("AGC MCU started")
    return LGW_HAL_SUCCESS


def _arb_mailbox_wait(status_val: int, timeout: float = 3.0) -> bool:
    """Wait for ARB MCU status register to reach the given value.

    Args:
        status_val: Expected status byte.
        timeout: Maximum wait time in seconds.

    Returns:
        True if status reached, False on timeout.
    """
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        if _reg_r("ARB_MCU_MCU_ARB_STATUS_MCU_ARB_STATUS") == status_val:
            return True
        time.sleep(0.001)
    log.error("ARB mailbox timeout waiting for status 0x%02X", status_val)
    return False


def _arb_start() -> int:
    """Execute the ARB MCU startup handshake sequence.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.
    """
    if not _arb_mailbox_wait(0x01):
        return LGW_HAL_ERROR
    version = _reg_r("ARB_MCU_ARB_DEBUG_STS_0_ARB_DEBUG_STS_0")
    if version != _FW_VERSION_ARB:
        log.error("ARB FW version mismatch: got %d expected %d", version, _FW_VERSION_ARB)
        return LGW_HAL_ERROR
    log.debug("ARB FW version: %d", version)

    # Enable debug stats on SF7
    _reg_w("ARB_MCU_ARB_DEBUG_CFG_0_ARB_DEBUG_CFG_0", 1)  # enable stats
    _reg_w("ARB_MCU_ARB_DEBUG_CFG_1_ARB_DEBUG_CFG_1", 7)  # SF7

    # Disable dual demodulation (no fine timestamp by default)
    _reg_w("ARB_MCU_ARB_DEBUG_CFG_3_ARB_DEBUG_CFG_3", 0x00)
    _reg_w("ARB_MCU_ARB_DEBUG_CFG_2_ARB_DEBUG_CFG_2", 3)   # filter threshold
    _reg_w("ARB_MCU_ARB_DEBUG_CFG_1_ARB_DEBUG_CFG_1", 1)   # resume

    if not _arb_mailbox_wait(0x00):
        return LGW_HAL_ERROR
    log.debug("ARB MCU started")
    return LGW_HAL_SUCCESS


# ---------------------------------------------------------------------------
# SX1302 core initialisation helpers
# ---------------------------------------------------------------------------


def _sx1302_radio_reset(rf_chain: int) -> None:
    """Reset the SX1250 radio on the given RF chain.

    Pulses RADIO_RST high for 500ms, deasserts, then re-asserts (SX1250 auto-cal).
    Must be called before _sx1250_setup().
    """
    _reg_w("COMMON_CTRL0_CLK32_RIF_CTRL", 0)
    if rf_chain == 0:
        _reg_w("AGC_MCU_RF_EN_A_RADIO_EN", 1)
        _reg_w("AGC_MCU_RF_EN_A_RADIO_RST", 1)
        time.sleep(0.5)
        _reg_w("AGC_MCU_RF_EN_A_RADIO_RST", 0)
        time.sleep(0.01)
        _reg_w("AGC_MCU_RF_EN_A_RADIO_RST", 1)
        time.sleep(0.01)
    else:
        _reg_w("AGC_MCU_RF_EN_B_RADIO_EN", 1)
        _reg_w("AGC_MCU_RF_EN_B_RADIO_RST", 1)
        time.sleep(0.5)
        _reg_w("AGC_MCU_RF_EN_B_RADIO_RST", 0)
        time.sleep(0.01)
        _reg_w("AGC_MCU_RF_EN_B_RADIO_RST", 1)
        time.sleep(0.01)
    log.debug("sx1302_radio_reset chain=%d done", rf_chain)


def _sx1302_radio_set_mode(rf_chain: int) -> None:
    """Set SX1302 radio frontend to SX1250 mode."""
    if rf_chain == 0:
        _reg_w("COMMON_CTRL0_SX1261_MODE_RADIO_A", 1)
    else:
        _reg_w("COMMON_CTRL0_SX1261_MODE_RADIO_B", 1)


def _sx1302_pa_lna_lut_configure(full_duplex: bool = False) -> None:
    """Configure PA and LNA LUT tables for the AGC MCU."""
    if full_duplex:
        _reg_w("AGC_MCU_LUT_TABLE_A_PA_LUT", 0x0C)
        _reg_w("AGC_MCU_LUT_TABLE_A_LNA_LUT", 0x0F)
    else:
        _reg_w("AGC_MCU_LUT_TABLE_A_PA_LUT", 0x04)
        _reg_w("AGC_MCU_LUT_TABLE_A_LNA_LUT", 0x02)
    _reg_w("AGC_MCU_LUT_TABLE_B_PA_LUT", 0x04)
    _reg_w("AGC_MCU_LUT_TABLE_B_LNA_LUT", 0x02)


def _sx1302_radio_fe_configure() -> None:
    """Configure SX1302 radio frontend RSSI filters and DC notch."""
    _reg_w("RADIO_FE_RSSI_BB_FILTER_ALPHA_RADIO_A_RSSI_BB_FILTER_ALPHA", 0x03)
    _reg_w("RADIO_FE_RSSI_DEC_FILTER_ALPHA_RADIO_A_RSSI_DEC_FILTER_ALPHA", 0x07)
    _reg_w("RADIO_FE_RSSI_BB_FILTER_ALPHA_RADIO_B_RSSI_BB_FILTER_ALPHA", 0x03)
    _reg_w("RADIO_FE_RSSI_DEC_FILTER_ALPHA_RADIO_B_RSSI_DEC_FILTER_ALPHA", 0x07)
    _reg_w("RADIO_FE_RSSI_DB_DEF_RADIO_A_RSSI_DB_DEFAULT_VALUE", 23)
    _reg_w("RADIO_FE_RSSI_DEC_DEF_RADIO_A_RSSI_DEC_DEFAULT_VALUE", 66)
    _reg_w("RADIO_FE_RSSI_DB_DEF_RADIO_B_RSSI_DB_DEFAULT_VALUE", 23)
    _reg_w("RADIO_FE_RSSI_DEC_DEF_RADIO_B_RSSI_DEC_DEFAULT_VALUE", 66)
    _reg_w("RADIO_FE_CTRL0_RADIO_A_DC_NOTCH_EN", 1)
    _reg_w("RADIO_FE_CTRL0_RADIO_A_HOST_FILTER_GAIN", 0x0B)
    _reg_w("RADIO_FE_CTRL0_RADIO_B_DC_NOTCH_EN", 1)
    _reg_w("RADIO_FE_CTRL0_RADIO_B_HOST_FILTER_GAIN", 0x0B)


def _sx1302_init() -> None:
    """Reset SX1302 internal state and configure GPIO lines."""
    _reg_w("GPIO_GPIO_DIR_L_DIRECTION", 0xFF)
    _reg_w("GPIO_GPIO_DIR_H_DIRECTION", 0x0F)


def _sx1302_radio_clock_select(clksrc: int) -> None:
    """Select the reference clock source for the SX1302.

    Matches C sx1302_radio_clock_select(): selects radio clock, enables clock
    dividers (CLKDIV_EN), and sets RIF clock to 32MHz (CLK32_RIF_CTRL=1).

    Args:
        clksrc: RF chain index (0 or 1) that supplies the clock.
    """
    if clksrc == 0:
        _reg_w("CLK_CTRL_CLK_SEL_CLK_RADIO_A_SEL", 1)
        _reg_w("CLK_CTRL_CLK_SEL_CLK_RADIO_B_SEL", 0)
    else:
        _reg_w("CLK_CTRL_CLK_SEL_CLK_RADIO_A_SEL", 0)
        _reg_w("CLK_CTRL_CLK_SEL_CLK_RADIO_B_SEL", 1)
    # Enable clock dividers and switch RIF to radio 32MHz clock
    _reg_w("CLK_CTRL_CLK_SEL_CLKDIV_EN", 1)
    _reg_w("COMMON_CTRL0_CLK32_RIF_CTRL", 1)


def _sx1302_channelizer_configure(if_chain_cfg: List[Optional[dict]]) -> None:
    """Write IF chain frequency offsets and radio select to channelizer.

    Args:
        if_chain_cfg: List of IF chain config dicts with 'freq_hz' and
            'rf_chain' keys.  None entries are skipped.
    """
    for i, cfg in enumerate(if_chain_cfg[:8]):
        if cfg is None:
            continue
        freq_word = round(cfg.get("freq_hz", 0) / 15.625)  # 15.625 kHz resolution
        msb = (freq_word >> 8) & 0x1F
        lsb = freq_word & 0xFF
        _reg_w(f"RX_TOP_FREQ_{i}_MSB_IF_FREQ_{i}", msb)
        _reg_w(f"RX_TOP_FREQ_{i}_LSB_IF_FREQ_{i}", lsb)

    # Build radio_select byte (one bit per channel)
    radio_sel = 0
    for i, cfg in enumerate(if_chain_cfg[:8]):
        if cfg and cfg.get("rf_chain", 0) == 1:
            radio_sel |= (1 << i)
    _reg_w("RX_TOP_RADIO_SELECT_RADIO_SELECT", radio_sel)


def _sx1302_lora_service_configure(cfg: Optional[dict]) -> None:
    """Configure the LoRa service modem (9th IF chain).

    Args:
        cfg: Config dict with 'freq_hz' and 'rf_chain' keys, or None.
    """
    if cfg is None:
        return
    freq_word = round(cfg.get("freq_hz", 0) / 15.625)
    _reg_w(
        "RX_TOP_LORA_SERVICE_FSK_LORA_SERVICE_FREQ_MSB_IF_FREQ_0",
        (freq_word >> 8) & 0x1F,
    )
    _reg_w(
        "RX_TOP_LORA_SERVICE_FSK_LORA_SERVICE_FREQ_LSB_IF_FREQ_0",
        freq_word & 0xFF,
    )
    _reg_w(
        "RX_TOP_LORA_SERVICE_FSK_LORA_SERVICE_RADIO_SEL_RADIO_SELECT",
        cfg.get("rf_chain", 0) & 0x01,
    )


def _sx1302_lora_syncword(lorawan_public: bool) -> None:
    """Set the LoRa sync word for the multi-SF correlator.

    Args:
        lorawan_public: If True, use public sync word (0x34).
            If False, use private sync word (0x12).
    """
    sw = 0x34 if lorawan_public else 0x12
    # Enable correlators for SF5-SF12 (all 8 correlators, 8 channels)
    _reg_w("RX_TOP_CORR_CLOCK_ENABLE_CLK_EN", 0xFF)
    _reg_w("RX_TOP_CORRELATOR_SF_EN_CORR_SF_EN", 0xFF)
    _reg_w("RX_TOP_CORRELATOR_EN_CORR_EN", 0xFF)
    log.debug("LoRa syncword set to 0x%02X (public=%s)", sw, lorawan_public)


# ---------------------------------------------------------------------------
# RX FIFO — packet fetch and parse
# ---------------------------------------------------------------------------


class _RxPacket:
    """Internal raw RX packet extracted from the SX1302 FIFO."""

    __slots__ = (
        "payload", "if_chain", "modem_id", "rssi_chan", "rssi_signal",
        "snr", "sf", "bw", "cr", "crc_en", "crc_error", "crc16",
        "freq_offset_error", "timestamp_us", "num_ts",
    )

    def __init__(self) -> None:
        self.payload: bytes = b""
        self.if_chain: int = 0
        self.modem_id: int = 0
        self.rssi_chan: int = 0
        self.rssi_signal: int = 0
        self.snr: int = 0
        self.sf: int = 0
        self.bw: int = 0
        self.cr: int = 0
        self.crc_en: int = 0
        self.crc_error: int = 0
        self.crc16: int = 0
        self.freq_offset_error: int = 0
        self.timestamp_us: int = 0
        self.num_ts: int = 0


def _rx_buffer_fetch() -> List[_RxPacket]:
    """Read and parse all pending packets from the SX1302 RX FIFO.

    Implements the double-read workaround for the nb_bytes register and the
    syncword scan algorithm described in the SX1302 HAL reference.

    Returns:
        List of parsed _RxPacket objects.
    """
    # Double-read workaround: hardware multi-byte register glitch
    nb_msb = _reg_r("RX_TOP_RX_BUFFER_NB_BYTES_MSB_RX_BUFFER_NB_BYTES")
    nb_lsb = _reg_r("RX_TOP_RX_BUFFER_NB_BYTES_LSB_RX_BUFFER_NB_BYTES")
    count1 = ((nb_msb & 0x1F) << 8) | (nb_lsb & 0xFF)

    nb_msb = _reg_r("RX_TOP_RX_BUFFER_NB_BYTES_MSB_RX_BUFFER_NB_BYTES")
    nb_lsb = _reg_r("RX_TOP_RX_BUFFER_NB_BYTES_LSB_RX_BUFFER_NB_BYTES")
    count2 = ((nb_msb & 0x1F) << 8) | (nb_lsb & 0xFF)

    buffer_size = max(count1, count2)
    if buffer_size == 0:
        return []
    if buffer_size < (_PKT_HEAD_METADATA + _PKT_TAIL_METADATA):
        log.debug("RX buffer too small (%d bytes), discarding", buffer_size)
        return []

    # Bulk read from RX_BUFFER base address
    buf = list(_spi_read(_SPI_MUX_TARGET_SX1302, _RX_BUFFER_BASE_ADDR, buffer_size))

    # Find first syncword 0xA5 0xC0
    sync_idx = -1
    for i in range(len(buf) - 1):
        if buf[i] == _PKT_SYNCWORD_H and buf[i + 1] == _PKT_SYNCWORD_L:
            sync_idx = i
            break
    if sync_idx < 0:
        log.debug("No syncword found in RX buffer")
        return []
    if sync_idx > 0:
        buf = buf[sync_idx:]  # re-align

    packets: List[_RxPacket] = []
    idx = 0
    while idx + _PKT_HEAD_METADATA + _PKT_TAIL_METADATA <= len(buf):
        if buf[idx] != _PKT_SYNCWORD_H or buf[idx + 1] != _PKT_SYNCWORD_L:
            break  # lost alignment

        payload_len = buf[idx + 2]
        # Head is 9 bytes: [syncH, syncL, payload_len, if_chain, modem_id, ...]
        head_start = idx
        pld_start = idx + _PKT_HEAD_METADATA
        tail_start = pld_start + payload_len
        num_ts_offset = tail_start + 21  # SX1302_PKT_NUM_TS_METRICS offset

        if num_ts_offset >= len(buf):
            break
        num_ts = buf[num_ts_offset] if num_ts_offset < len(buf) else 0
        packet_end = tail_start + _PKT_TAIL_METADATA + 2 * num_ts

        if packet_end > len(buf):
            break

        pkt = _RxPacket()
        pkt.payload = bytes(buf[pld_start: pld_start + payload_len])

        # Parse head metadata (bytes 3-8 of head block)
        pkt.if_chain = buf[head_start + 3] & 0x0F
        pkt.modem_id = (buf[head_start + 3] >> 4) & 0x0F

        # Parse tail metadata
        tail = buf[tail_start: tail_start + _PKT_TAIL_METADATA]
        if len(tail) >= 14:
            pkt.rssi_chan = tail[0]
            pkt.rssi_signal = tail[1]
            pkt.snr = tail[2]
            pkt.crc_en = tail[3] & 0x01
            pkt.crc_error = (tail[3] >> 1) & 0x01
            pkt.crc16 = (tail[4] << 8) | tail[5]
            rate_byte = tail[6]
            pkt.sf = rate_byte & 0x0F
            pkt.bw = (rate_byte >> 4) & 0x0F
            pkt.cr = tail[7] & 0x07
            pkt.freq_offset_error = struct.unpack_from(">h", bytes(tail[8:10]))[0]
            pkt.timestamp_us = struct.unpack_from("<I", bytes(tail[10:14]))[0]
            pkt.num_ts = num_ts

        packets.append(pkt)
        idx = packet_end

    return packets


# ---------------------------------------------------------------------------
# Public HAL API
# ---------------------------------------------------------------------------


def lgw_board_setconf(conf: dict) -> int:
    """Set gateway board configuration.

    Must be called before lgw_start().

    Args:
        conf: Dictionary with keys:
            ``lorawan_public`` (bool): Use public LoRa sync word (0x34).
            ``clksrc`` (int): RF chain index (0 or 1) providing the reference
                clock.
            ``spi_path`` (str): Linux spidev path (default ``/dev/spidev0.0``).

    Returns:
        LGW_HAL_SUCCESS.

    Example:
        >>> lgw_board_setconf({"lorawan_public": True, "clksrc": 0,
        ...                    "spi_path": "/dev/spidev0.0"})
        0
    """
    global _board_cfg, _spi_path
    if _started:
        log.error("lgw_board_setconf: gateway already started")
        return LGW_HAL_ERROR
    cfg = _normalize_config(conf)
    _board_cfg = cfg
    _spi_path = cfg.get("spi_path", "/dev/spidev0.0")
    return LGW_HAL_SUCCESS


def lgw_rxrf_setconf(rf_chain: int, conf: dict) -> int:
    """Set RX RF chain configuration.

    Must be called before lgw_start().

    Args:
        rf_chain: RF chain index (0 or 1).
        conf: Dictionary with keys:
            ``enable`` (bool): Enable this RF chain.
            ``freq_hz`` (int): Centre frequency in Hz.
            ``rssi_offset`` (float): RSSI offset in dBm.
            ``type`` (int): Radio type constant (RADIO_TYPE_SX1250, etc.).
            ``tx_enable`` (bool): Allow TX on this chain.
            ``single_input_mode`` (bool): Single-ended RF input.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.

    Example:
        >>> lgw_rxrf_setconf(0, {"enable": True, "freq_hz": 868100000,
        ...                      "type": RADIO_TYPE_SX1250})
        0
    """
    if rf_chain >= LGW_RF_CHAIN_NB:
        log.error("lgw_rxrf_setconf: invalid rf_chain %d", rf_chain)
        return LGW_HAL_ERROR
    if _started:
        log.error("lgw_rxrf_setconf: gateway already started")
        return LGW_HAL_ERROR
    _rf_chain_cfg[rf_chain] = _normalize_config(conf)
    return LGW_HAL_SUCCESS


def lgw_rxif_setconf(if_chain: int, conf: dict) -> int:
    """Set RX IF chain configuration.

    Must be called before lgw_start().

    Args:
        if_chain: IF chain index (0-9, where 8 = LoRa service, 9 = FSK).
        conf: Dictionary with keys:
            ``enable`` (bool): Enable this IF chain.
            ``rf_chain`` (int): Parent RF chain (0 or 1).
            ``freq_hz`` (int): IF frequency offset in Hz.
            ``bandwidth`` (int): BW_* constant.
            ``datarate`` (int): DR_LORA_SF* or FSK bit rate.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.

    Example:
        >>> lgw_rxif_setconf(0, {"enable": True, "rf_chain": 0,
        ...                      "freq_hz": -400000, "bandwidth": BW_125KHZ,
        ...                      "datarate": DR_LORA_MULTI})
        0
    """
    if if_chain >= len(_if_chain_cfg):
        log.error("lgw_rxif_setconf: invalid if_chain %d", if_chain)
        return LGW_HAL_ERROR
    if _started:
        log.error("lgw_rxif_setconf: gateway already started")
        return LGW_HAL_ERROR
    _if_chain_cfg[if_chain] = _normalize_config(conf)
    return LGW_HAL_SUCCESS


def lgw_txgain_setconf(rf_chain: int, conf: dict) -> int:
    """Set TX gain look-up table for an RF chain.

    Must be called before lgw_start().

    Args:
        rf_chain: RF chain index (0 or 1).
        conf: Dictionary with key ``lut`` — a list of gain table entries,
            each a dict with ``pa_gain``, ``dig_gain``, ``dac_gain``, ``mix_gain``
            and ``rf_power`` keys.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.

    Example:
        >>> lgw_txgain_setconf(0, {"lut": [{"pa_gain": 3, "rf_power": 14}]})
        0
    """
    if rf_chain >= LGW_RF_CHAIN_NB:
        log.error("lgw_txgain_setconf: invalid rf_chain %d", rf_chain)
        return LGW_HAL_ERROR
    if _started:
        log.error("lgw_txgain_setconf: gateway already started")
        return LGW_HAL_ERROR
    if _rf_chain_cfg[rf_chain] is None:
        _rf_chain_cfg[rf_chain] = {}
    cfg = _normalize_config(conf)
    _rf_chain_cfg[rf_chain]["tx_lut"] = cfg.get("lut", [])  # type: ignore[index]
    return LGW_HAL_SUCCESS


def _record_pre_start_config(name: str, conf: Any) -> int:
    """Record a C-HAL-compatible configuration block before lgw_start()."""
    if _started:
        log.error("%s: gateway already started", name)
        return LGW_HAL_ERROR
    globals()[name] = _normalize_config(conf)
    return LGW_HAL_SUCCESS


def lgw_demod_setconf(conf: Any) -> int:
    """Record demodulator configuration for C HAL API compatibility.

    The pure-Python HAL currently configures SX1302 demodulators from the RX IF
    chain table in :func:`lgw_start`.  This function keeps the Semtech C HAL
    surface available for callers that provide an extra demodulator config
    block, without claiming new hardware capability.
    """
    return _record_pre_start_config("_demod_cfg", conf)


def lgw_ftime_setconf(conf: Any) -> int:
    """Record fine-timestamp configuration for C HAL API compatibility.

    Fine timestamping is not implemented yet (see capabilities), but accepting
    and preserving the pre-start config lets higher layers use the same setup
    path across C HAL and Python HAL backends.
    """
    return _record_pre_start_config("_ftime_cfg", conf)


def lgw_debug_setconf(conf: Any) -> int:
    """Record debug configuration for C HAL API compatibility."""
    return _record_pre_start_config("_debug_cfg", conf)


def lgw_sx1261_setconf(conf: Any) -> int:
    """Set SX1261 companion-chip configuration.

    This is intentionally a configuration scaffold: it records the companion,
    spectral-scan, and LBT policy shape without claiming full Semtech C HAL
    hardware LBT/spectral parity yet.
    """
    global _sx1261_cfg
    if _started:
        log.error("lgw_sx1261_setconf: gateway already started")
        return LGW_HAL_ERROR

    cfg = _normalize_config(conf)
    lbt_cfg = dict(cfg.get("lbt") or {})
    channels = list(lbt_cfg.get("channels") or [])
    if len(channels) > LGW_LBT_CHANNEL_NB_MAX:
        log.error(
            "lgw_sx1261_setconf: too many LBT channels (%d > %d)",
            len(channels),
            LGW_LBT_CHANNEL_NB_MAX,
        )
        return LGW_HAL_ERROR

    lbt_cfg["channels"] = channels
    cfg["lbt"] = lbt_cfg
    _sx1261_cfg = cfg
    return LGW_HAL_SUCCESS


def lgw_sx1261_getconf() -> Optional[Dict[str, Any]]:
    """Return a shallow copy of the configured SX1261 companion state."""
    if _sx1261_cfg is None:
        return None
    cfg = dict(_sx1261_cfg)
    if isinstance(cfg.get("lbt"), dict):
        lbt_cfg = dict(cfg["lbt"])
        lbt_cfg["channels"] = list(lbt_cfg.get("channels") or [])
        cfg["lbt"] = lbt_cfg
    return cfg


def lgw_spectral_scan_start(freq_hz: int, nb_scan: int = 1) -> int:
    """Start a placeholder SX1261 spectral scan.

    The pure-Python HAL does not yet read real scan bins from SX1261. This
    scaffold records requested scan state so CAD/LBT can be designed against a
    stable API before hardware-level spectral implementation lands.
    """
    if not (_sx1261_cfg and _sx1261_cfg.get("enable")):
        log.error("lgw_spectral_scan_start: SX1261 companion is not enabled")
        return LGW_HAL_ERROR
    _spectral_scan_state.update(
        {
            "active": True,
            "freq_hz": int(freq_hz),
            "nb_scan": int(nb_scan),
            "results": [],
            "status": "running",
        }
    )
    return LGW_HAL_SUCCESS


def lgw_spectral_scan_get_status() -> str:
    """Return placeholder spectral scan status."""
    return str(_spectral_scan_state.get("status", "idle"))


def lgw_spectral_scan_get_results() -> List[Any]:
    """Return placeholder spectral scan result bins."""
    return list(_spectral_scan_state.get("results", []))


def lgw_spectral_scan_abort() -> int:
    """Abort the placeholder SX1261 spectral scan."""
    _spectral_scan_state.update({"active": False, "status": "aborted"})
    return LGW_HAL_SUCCESS


def lgw_start() -> int:
    """Start the LoRa gateway.

    Opens the SPI device, calibrates and configures the radio chains, loads
    and starts the AGC and ARB MCU firmware, and enables the RX path.

    Requires lgw_board_setconf(), lgw_rxrf_setconf(), and lgw_rxif_setconf()
    to have been called first.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.

    Example:
        >>> lgw_board_setconf({"lorawan_public": True, "clksrc": 0,
        ...                    "spi_path": "/dev/spidev0.0"})
        0
        >>> ret = lgw_start()
    """
    global _started
    if _started:
        log.error("lgw_start: already started")
        return LGW_HAL_ERROR
    if _board_cfg is None:
        log.error("lgw_start: board config not set")
        return LGW_HAL_ERROR

    # Open SPI
    try:
        _spi_open(_spi_path)
    except Exception as exc:
        log.error("lgw_start: SPI open failed: %s", exc)
        return LGW_HAL_ERROR

    clksrc = _board_cfg.get("clksrc", 0)
    lorawan_public = bool(_board_cfg.get("lorawan_public", True))

    # Ensure host controls the radio SPI mux (registers may persist from a previous run)
    _reg_w("COMMON_CTRL0_HOST_RADIO_CTRL", 1)

    # Phase 1: Calibration (matches C sx1302_radio_calibrate)
    # Reset and set mode for each enabled radio
    for i, rf_cfg in enumerate(_rf_chain_cfg):
        if rf_cfg and rf_cfg.get("enable"):
            _sx1302_radio_reset(i)
            _sx1302_radio_set_mode(i)

    # Clock select must happen before calibrate
    _sx1302_radio_clock_select(clksrc)

    # Disable PA/LNA during calibration
    _reg_w("AGC_MCU_CTRL_FORCE_HOST_FE_CTRL", 1)
    _reg_w("AGC_MCU_RF_EN_A_PA_EN", 0)
    _reg_w("AGC_MCU_RF_EN_A_LNA_EN", 0)

    # SX1250 image calibration for each enabled chain
    for i, rf_cfg in enumerate(_rf_chain_cfg):
        if rf_cfg and rf_cfg.get("enable"):
            freq_hz = rf_cfg.get("freq_hz", 0)
            _sx1250_calibrate(i, freq_hz)

    # Phase 2: Full radio setup (matches C lgw_start radio setup loop)
    for i, rf_cfg in enumerate(_rf_chain_cfg):
        if rf_cfg and rf_cfg.get("enable"):
            freq_hz = rf_cfg.get("freq_hz", 0)
            single_input = bool(rf_cfg.get("single_input_mode", False))
            _sx1302_radio_reset(i)
            _sx1250_setup(i, freq_hz, single_input)
            _sx1302_radio_set_mode(i)

    # Select reference clock (done again after setup, per C lgw_start)
    _sx1302_radio_clock_select(clksrc)

    # Release host FE control and radio SPI control to AGC MCU
    _reg_w("AGC_MCU_CTRL_FORCE_HOST_FE_CTRL", 0)
    _reg_w("COMMON_CTRL0_HOST_RADIO_CTRL", 0)

    # Core SX1302 init
    _sx1302_init()

    # Configure PA/LNA LUT tables (required for AGC MCU)
    full_duplex = bool(_board_cfg.get("full_duplex", False))
    _sx1302_pa_lna_lut_configure(full_duplex)

    # Configure radio frontend RSSI filters and DC notch
    _sx1302_radio_fe_configure()

    # Configure channelizer
    _sx1302_channelizer_configure(_if_chain_cfg[:8])

    # Configure LoRa service modem (IF chain 8)
    _sx1302_lora_service_configure(_if_chain_cfg[8] if len(_if_chain_cfg) > 8 else None)

    # Set LoRa sync word
    _sx1302_lora_syncword(lorawan_public)

    # Enable demodulators before starting AGC/ARB (per C lgw_start sx1302_modem_enable)
    _reg_w("COMMON_GEN_CONCENTRATOR_MODEM_ENABLE", 1)
    _reg_w("COMMON_GEN_MBWSSF_MODEM_ENABLE", 1)
    _reg_w("COMMON_GEN_FSK_MODEM_ENABLE", 1)
    _reg_w("COMMON_GEN_GLOBAL_EN", 1)

    # Load and start AGC firmware
    ret = _agc_load_firmware(_AGC_FW_SX1250)
    if ret != LGW_HAL_SUCCESS:
        _spi_close()
        return LGW_HAL_ERROR
    ret = _agc_start()
    if ret != LGW_HAL_SUCCESS:
        _spi_close()
        return LGW_HAL_ERROR

    # Load and start ARB firmware
    ret = _arb_load_firmware(_ARB_FW)
    if ret != LGW_HAL_SUCCESS:
        _spi_close()
        return LGW_HAL_ERROR
    ret = _arb_start()
    if ret != LGW_HAL_SUCCESS:
        _spi_close()
        return LGW_HAL_ERROR

    _started = True
    log.info("lgw_start: gateway started")
    return LGW_HAL_SUCCESS


def lgw_stop() -> int:
    """Stop the LoRa gateway and release the SPI device.

    Aborts any in-progress TX operations, then closes the SPI bus.

    Returns:
        LGW_HAL_SUCCESS.

    Example:
        >>> lgw_stop()
        0
    """
    global _started
    if not _started:
        return LGW_HAL_SUCCESS

    # Abort TX on both chains
    for reg in (
        "TX_TOP_A_TX_TRIG_TX_TRIG_IMMEDIATE",
        "TX_TOP_B_TX_TRIG_TX_TRIG_IMMEDIATE",
    ):
        try:
            _reg_w(reg, 0)
        except Exception:
            pass

    _spi_close()
    _started = False
    log.info("lgw_stop: gateway stopped")
    return LGW_HAL_SUCCESS


def lgw_abort_tx() -> int:
    """Abort pending TX operations on all RF chains.

    This mirrors the Semtech C HAL API entry point.  It is intentionally safe
    to call before :func:`lgw_start`, where it becomes a no-op success.
    """
    if not _started:
        return LGW_HAL_SUCCESS

    for prefix in ("TX_TOP_A", "TX_TOP_B"):
        try:
            _reg_w(f"{prefix}_TX_TRIG_TX_TRIG_IMMEDIATE", 0)
            _reg_w(f"{prefix}_TX_TRIG_TX_TRIG_DELAYED", 0)
        except Exception as exc:
            log.error("lgw_abort_tx: %s", exc)
            return LGW_HAL_ERROR
    return LGW_HAL_SUCCESS


def lgw_receive(max_pkt: int) -> List[dict]:
    """Fetch received packets from the SX1302 hardware FIFO.

    Reads the RX buffer, parses all pending packets, and returns at most
    ``max_pkt`` of them as dictionaries.

    Args:
        max_pkt: Maximum number of packets to return.

    Returns:
        List of packet dictionaries, each with keys:
            ``freq_hz`` (int): Centre frequency in Hz.
            ``if_chain`` (int): IF chain index that received the packet.
            ``rf_chain`` (int): RF chain index.
            ``modulation`` (int): MOD_LORA or MOD_FSK.
            ``bandwidth`` (int): BW_* constant.
            ``datarate`` (int): Spreading factor (DR_LORA_SF*) or FSK bps.
            ``coderate`` (int): CR_LORA_* constant.
            ``rssi`` (float): Channel RSSI in dBm.
            ``snr`` (float): Signal-to-noise ratio in dB.
            ``crc_en`` (bool): CRC was enabled.
            ``crc_error`` (bool): CRC check failed.
            ``timestamp_us`` (int): RX timestamp in microseconds.
            ``size`` (int): Payload length in bytes.
            ``payload`` (bytes): Raw payload bytes.

    Example:
        >>> pkts = lgw_receive(8)
        >>> for p in pkts:
        ...     print(p["payload"])
    """
    if not _started:
        log.error("lgw_receive: gateway not started")
        return []

    raw_pkts = _rx_buffer_fetch()
    results: List[dict] = []

    for raw in raw_pkts[:max_pkt]:
        if_idx = raw.if_chain & 0x0F
        rf_chain = 0
        freq_hz = 0
        if if_idx < 8 and if_idx < len(_if_chain_cfg) and _if_chain_cfg[if_idx]:
            cfg = _if_chain_cfg[if_idx]
            rf_chain = cfg.get("rf_chain", 0)  # type: ignore[union-attr]
            if_freq = cfg.get("freq_hz", 0)  # type: ignore[union-attr]
            rf_freq = 0
            if rf_chain < len(_rf_chain_cfg) and _rf_chain_cfg[rf_chain]:
                rf_freq = _rf_chain_cfg[rf_chain].get("freq_hz", 0)  # type: ignore
            freq_hz = rf_freq + if_freq

        # Map SF code to DR constant
        sf_map = {
            5: DR_LORA_SF5, 6: DR_LORA_SF6, 7: DR_LORA_SF7, 8: DR_LORA_SF8,
            9: DR_LORA_SF9, 10: DR_LORA_SF10, 11: DR_LORA_SF11, 12: DR_LORA_SF12,
        }
        # Map BW code (hardware) to BW_* constant
        bw_map = {4: BW_125KHZ, 5: BW_250KHZ, 6: BW_500KHZ}

        results.append({
            "freq_hz": freq_hz,
            "if_chain": if_idx,
            "rf_chain": rf_chain,
            "modulation": MOD_LORA,
            "bandwidth": bw_map.get(raw.bw, BW_UNDEFINED),
            "datarate": sf_map.get(raw.sf, DR_UNDEFINED),
            "coderate": raw.cr,
            "rssi": float(raw.rssi_chan) - 64.0,  # dBm offset
            "snr": float(raw.snr) / 4.0,
            "crc_en": bool(raw.crc_en),
            "crc_error": bool(raw.crc_error),
            "timestamp_us": raw.timestamp_us,
            "size": len(raw.payload),
            "payload": raw.payload,
        })

    return results


def lgw_time_on_air(pkt: Dict[str, Any]) -> int:
    """Return LoRa packet time-on-air in milliseconds.

    This mirrors the Semtech HAL helper closely enough for scheduling, LBT,
    and future duty-cycle policy. Unsupported modulations return 0.
    """
    if pkt.get("modulation", MOD_LORA) != MOD_LORA:
        return 0

    payload = pkt.get("payload", b"")
    payload_len = int(pkt.get("size", len(payload)))
    sf = int(pkt.get("datarate", DR_LORA_SF7))
    if sf == DR_LORA_MULTI or sf < 5:
        return 0

    bw_hz = pkt.get("bandwidth_hz")
    if bw_hz is None:
        bw_code = pkt.get("bandwidth", BW_125KHZ)
        bw_hz = {
            BW_125KHZ: 125_000,
            BW_250KHZ: 250_000,
            BW_500KHZ: 500_000,
        }.get(bw_code, 0)
    bw_hz = int(bw_hz)
    if bw_hz <= 0:
        return 0

    coderate = int(pkt.get("coderate", CR_LORA_4_5))
    cr = coderate - 4 if coderate in (5, 6, 7, 8) else coderate
    if cr < CR_LORA_4_5 or cr > CR_LORA_4_8:
        return 0

    preamble = int(pkt.get("preamble", 8))
    explicit_header = not bool(pkt.get("no_header", False))
    crc_enabled = not bool(pkt.get("no_crc", False))
    tsym_s = (2 ** sf) / float(bw_hz)
    low_data_rate_optimize = 1 if tsym_s >= 0.016 else 0
    crc_bits = 16 if crc_enabled else 0
    header_bits = 0 if explicit_header else 20
    denominator = 4 * (sf - 2 * low_data_rate_optimize)
    numerator = 8 * payload_len - 4 * sf + 28 + crc_bits - header_bits
    payload_symbols = 8 + max(math.ceil(numerator / denominator) * cr, 0)
    total_symbols = preamble + 4.25 + payload_symbols
    return int(math.ceil(total_symbols * tsym_s * 1000.0))


def lgw_send(pkt: dict) -> int:
    """Transmit a packet via the SX1302.

    Validates packet parameters and queues the packet for transmission.

    Args:
        pkt: Packet dictionary with keys:
            ``rf_chain`` (int): RF chain to transmit on (0 or 1).
            ``freq_hz`` (int): TX frequency in Hz.
            ``modulation`` (int): MOD_LORA or MOD_FSK.
            ``bandwidth`` (int): BW_125KHZ, BW_250KHZ, or BW_500KHZ only.
            ``datarate`` (int): DR_LORA_SF* constant or FSK bit rate in bps.
            ``coderate`` (int): CR_LORA_* constant.
            ``tx_mode`` (int): TX_IMMEDIATE or TX_TIMESTAMPED.
            ``count_us`` (int): TX timestamp in microseconds (TX_TIMESTAMPED).
            ``rf_power`` (int): TX power in dBm.
            ``preamble`` (int): Number of preamble symbols.
            ``no_crc`` (bool): If True, transmit without CRC.
            ``no_header`` (bool): If True, transmit in implicit header mode.
            ``payload`` (bytes): Payload to transmit.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.

    Example:
        >>> lgw_send({"rf_chain": 0, "freq_hz": 868100000,
        ...           "modulation": MOD_LORA, "bandwidth": BW_125KHZ,
        ...           "datarate": DR_LORA_SF7, "coderate": CR_LORA_4_5,
        ...           "tx_mode": TX_IMMEDIATE, "rf_power": 14,
        ...           "payload": b"hello"})
        0
    """
    if not _started:
        log.error("lgw_send: gateway not started")
        return LGW_HAL_ERROR

    rf_chain = pkt.get("rf_chain", 0)
    if rf_chain >= LGW_RF_CHAIN_NB:
        log.error("lgw_send: invalid rf_chain %d", rf_chain)
        return LGW_HAL_ERROR

    rf_cfg = _rf_chain_cfg[rf_chain]
    if not (rf_cfg and rf_cfg.get("enable") and rf_cfg.get("tx_enable")):
        log.error("lgw_send: rf_chain %d not enabled for TX", rf_chain)
        return LGW_HAL_ERROR

    modulation = pkt.get("modulation", MOD_LORA)
    if modulation == MOD_LORA:
        bw = pkt.get("bandwidth", BW_UNDEFINED)
        if bw not in (BW_125KHZ, BW_250KHZ, BW_500KHZ):
            log.error("lgw_send: unsupported bandwidth %d (SX1302: 125/250/500 kHz only)", bw)
            return LGW_HAL_ERROR
        dr = pkt.get("datarate", DR_UNDEFINED)
        if dr not in range(DR_LORA_SF5, DR_LORA_SF12 + 1):
            log.error("lgw_send: invalid datarate %d", dr)
            return LGW_HAL_ERROR

    payload: bytes = pkt.get("payload", b"")
    tx_mode = pkt.get("tx_mode", TX_IMMEDIATE)
    count_us = pkt.get("count_us", 0)

    # Select TX block registers by rf_chain
    prefix = "TX_TOP_A" if rf_chain == 0 else "TX_TOP_B"

    # Write payload to TX buffer
    _reg_wb(f"{prefix}_TXRX_CFG0_3_PAYLOAD_LENGTH", bytes([len(payload)]))
    # Trigger TX
    if tx_mode == TX_IMMEDIATE:
        _reg_w(f"{prefix}_TX_TRIG_TX_TRIG_IMMEDIATE", 1)
    else:
        # Write timestamp and use timestamped trigger
        ts_bytes = struct.pack("<I", count_us & 0xFFFFFFFF)
        _reg_wb(f"{prefix}_TX_TRIG_TX_TRIG_IMMEDIATE", ts_bytes)
        _reg_w(f"{prefix}_TX_TRIG_TX_TRIG_DELAYED", 1)

    log.debug("lgw_send: queued %d bytes on rf_chain=%d", len(payload), rf_chain)
    return LGW_HAL_SUCCESS


def lgw_get_trigcnt() -> Tuple[int, int]:
    """Read the internal SX1302 free-running timestamp counter.

    Returns:
        Tuple of (status_code, count_us) where status_code is LGW_HAL_SUCCESS
        or LGW_HAL_ERROR and count_us is the 32-bit microsecond counter.

    Example:
        >>> status, ts = lgw_get_trigcnt()
        >>> print(ts)
        1234567
    """
    if not _started:
        return LGW_HAL_ERROR, 0
    b3 = _reg_r("TIMESTAMP_TIMESTAMP_MSB2_TIMESTAMP")
    b2 = _reg_r("TIMESTAMP_TIMESTAMP_MSB1_TIMESTAMP")
    b1 = _reg_r("TIMESTAMP_TIMESTAMP_LSB2_TIMESTAMP")
    b0 = _reg_r("TIMESTAMP_TIMESTAMP_LSB1_TIMESTAMP")
    count_us = ((b3 & 0xFF) << 24) | ((b2 & 0xFF) << 16) | ((b1 & 0xFF) << 8) | (b0 & 0xFF)
    return LGW_HAL_SUCCESS, count_us


def lgw_get_instcnt() -> Tuple[int, int]:
    """Return the SX1302 instant counter using the Semtech C HAL name.

    The pure-Python HAL's trigger counter and instant counter are backed by the
    same 32-bit microsecond timestamp register today.
    """
    return lgw_get_trigcnt()


def lgw_get_eui() -> Tuple[int, bytes]:
    """Read gateway EUI from SX1302 OTP.

    Returns:
        Tuple of (status_code, eui_bytes) where eui_bytes is an 8-byte EUI-64.
        Returns all-zeros EUI if OTP is not programmed.

    Example:
        >>> status, eui = lgw_get_eui()
        >>> print(eui.hex())
    """
    if not _started:
        return LGW_HAL_ERROR, b"\x00" * 8
    eui = bytearray(8)
    try:
        for i in range(8):
            _reg_w("OTP_BYTE_ADDR_ADDR", i)
            eui[i] = _reg_r("OTP_RD_DATA_RD_DATA") & 0xFF
    except Exception as exc:
        log.warning("lgw_get_eui: OTP read failed: %s", exc)
        return LGW_HAL_ERROR, bytes(8)
    return LGW_HAL_SUCCESS, bytes(eui)


def lgw_get_temperature() -> Tuple[int, float]:
    """Read internal temperature from the I2C sensor (if configured).

    This implementation returns a placeholder value.  Wire in an actual
    I2C read (e.g. via smbus2) if the board has the TMP sensor populated.

    Returns:
        Tuple of (status_code, temperature_celsius).

    Example:
        >>> status, temp = lgw_get_temperature()
        >>> print(f"{temp:.1f} C")
    """
    return LGW_HAL_SUCCESS, 25.0


def lgw_reg_w(reg_name: str, value: int) -> int:
    """Write a named SX1302 register.

    Args:
        reg_name: Register name from the _REG map.
        value: Value to write.

    Returns:
        LGW_HAL_SUCCESS or LGW_HAL_ERROR.

    Example:
        >>> lgw_reg_w("COMMON_PAGE_PAGE", 0)
        0
    """
    try:
        _reg_w(reg_name, value)
        return LGW_HAL_SUCCESS
    except (KeyError, ValueError) as exc:
        log.error("lgw_reg_w(%s): %s", reg_name, exc)
        return LGW_HAL_ERROR


def lgw_reg_r(reg_name: str) -> Tuple[int, int]:
    """Read a named SX1302 register.

    Args:
        reg_name: Register name from the _REG map.

    Returns:
        Tuple of (status_code, value).

    Example:
        >>> status, val = lgw_reg_r("COMMON_VERSION_VERSION")
        >>> print(val)
    """
    try:
        return LGW_HAL_SUCCESS, _reg_r(reg_name)
    except KeyError as exc:
        log.error("lgw_reg_r(%s): %s", reg_name, exc)
        return LGW_HAL_ERROR, 0


def lgw_status(rf_chain: int, select: int) -> Tuple[int, int]:
    """Query TX or RX status of an RF chain.

    Args:
        rf_chain: RF chain index (0 or 1).
        select: 0 for TX status, 1 for RX status.

    Returns:
        Tuple of (status_code, state) where state is a hardware status value.

    Example:
        >>> status, tx_state = lgw_status(0, 0)
    """
    if not _started:
        return LGW_HAL_ERROR, 0
    if rf_chain >= LGW_RF_CHAIN_NB:
        return LGW_HAL_ERROR, 0
    prefix = "TX_TOP_A" if rf_chain == 0 else "TX_TOP_B"
    try:
        # Accept both the C-HAL-compatible selector constants added above and
        # the original legacy 0/1 values used by this early Python HAL.
        if select in (0, TX_STATUS):
            state = _reg_r(f"{prefix}_LORA_TX_STATE_STATUS")
        elif select in (1, RX_STATUS):
            state = _reg_r("RX_TOP_MODEM_STATE_RX_MODEM_STATE")
        else:
            return LGW_HAL_ERROR, 0
        return LGW_HAL_SUCCESS, state
    except Exception as exc:
        log.error("lgw_status: %s", exc)
        return LGW_HAL_ERROR, 0


